import { PGlite } from "@electric-sql/pglite";
import { PGLiteSocketServer } from "@electric-sql/pglite-socket";
import { hashPassword } from "better-auth/crypto";
import { randomUUID } from "node:crypto";
import { readFile, readdir } from "node:fs/promises";
import { spawn } from "node:child_process";
import assert from "node:assert/strict";

// The database is in memory and contains only records generated by this run.
const db = await PGlite.create();
const databaseServer = new PGLiteSocketServer({
  db,
  host: "127.0.0.1",
  port: 35471,
});
const origin = "http://localhost:3317";
const env = {
  ...process.env,
  NODE_ENV: "production",
  DATABASE_URL: "postgresql://postgres:postgres@127.0.0.1:35471/postgres",
  DATABASE_POOL_MAX: "1",
  BETTER_AUTH_URL: origin,
  NEXT_PUBLIC_APP_URL: origin,
  BETTER_AUTH_SECRET: randomUUID() + randomUUID(),
  BASELINE_OWNER_EMAIL: "",
  BASELINE_MAIL_TRANSPORT: "resend",
  GOOGLE_CLIENT_ID: "",
  GOOGLE_CLIENT_SECRET: "",
  RESEND_API_KEY: "",
  RESEND_FROM_EMAIL: "",
};
let app;
function run(command, args) {
  return new Promise((resolve, reject) => {
    const child = spawn(command, args, { env, stdio: "inherit" });
    child.on("error", reject);
    child.on("exit", (code) =>
      code === 0
        ? resolve()
        : reject(new Error("The local production build failed.")),
    );
  });
}
async function ready() {
  for (let attempt = 0; attempt < 90; attempt++) {
    if (app.exitCode !== null)
      throw new Error("The local production process stopped.");
    try {
      if ((await fetch(origin + "/demo")).ok) return;
    } catch {}
    await new Promise((resolve) => setTimeout(resolve, 1000));
  }
  throw new Error("The local production app did not become ready.");
}
const request = (route, options = {}) =>
  fetch(origin + route, { ...options, redirect: "manual" });
const post = (route, body, cookie) =>
  request("/api/auth/" + route, {
    method: "POST",
    headers: {
      origin,
      "content-type": "application/json",
      ...(cookie && { cookie }),
    },
    body: JSON.stringify(body),
  });
async function login(fixture) {
  let result;
  for (let attempt = 0; attempt < 3; attempt++) {
    result = await post("sign-in/email", {
      email: fixture.email,
      password: fixture.password,
    });
    if (result.status !== 429) break;
    const seconds = Number(result.headers.get("retry-after")) || 10;
    await new Promise((resolve) =>
      setTimeout(resolve, Math.min(60, seconds + 1) * 1000),
    );
  }
  assert.equal(result.status, 200);
  return result.headers
    .getSetCookie()
    .map((value) => value.split(";")[0])
    .join("; ");
}

try {
  for (const migration of (await readdir("database/migrations")).sort())
    await db.exec(await readFile("database/migrations/" + migration, "utf8"));
  const fixtures = [];
  for (const steps of [10, 20]) {
    const id = randomUUID(),
      password = randomUUID(),
      email = id + "@example.test";
    await db.query(
      "INSERT INTO users(id,email,display_name,email_verified) VALUES($1,$2,'Release fixture',true)",
      [id, email],
    );
    await db.query(
      "INSERT INTO user_accounts(id,account_id,provider_id,user_id,password) VALUES($1,$2,'credential',$3,$4)",
      [randomUUID(), id, id, await hashPassword(password)],
    );
    await db.query(
      "INSERT INTO daily_metrics(id,user_id,metric_date,steps,move_calories,rest_minutes,breathwork_minutes,source) VALUES($1,$2,'2026-11-01',$3,0,0,0,'manual')",
      [randomUUID(), id, steps],
    );
    fixtures.push({ id, email, password, steps });
  }
  await databaseServer.start();
  await run("npm", ["run", "build"]);
  app = spawn(
    process.execPath,
    [
      "node_modules/next/dist/bin/next",
      "start",
      "-H",
      "127.0.0.1",
      "-p",
      "3317",
    ],
    { env, stdio: "ignore" },
  );
  await ready();
  assert.equal((await request("/api/metrics")).status, 401);
  assert.equal((await request("/home")).status, 307);
  const blockedEmail = randomUUID() + "@example.test",
    blockedPassword = randomUUID();
  const signup = await post("sign-up/email", {
    name: "Unapproved fixture",
    email: blockedEmail,
    password: blockedPassword,
  });
  assert([200, 403].includes(signup.status));
  assert.equal(
    (
      await post("sign-in/email", {
        email: blockedEmail,
        password: blockedPassword,
      })
    ).status,
    401,
  );
  assert.equal(
    (await db.query("SELECT id FROM users WHERE email=$1", [blockedEmail])).rows
      .length,
    0,
  );
  for (const fixture of fixtures) {
    let cookie = await login(fixture);
    const response = await request(
      "/api/metrics?userId=" +
        fixtures.find((value) => value.id !== fixture.id).id,
      { headers: { cookie } },
    );
    assert.equal(response.status, 200);
    const records = (await response.json()).metrics;
    assert.equal(records.length, 1);
    assert.equal(records[0].steps, fixture.steps);
    assert.equal((await request("/home", { headers: { cookie } })).status, 200);
    await db.query(
      "UPDATE user_sessions SET expires_at=now()-interval '1 minute' WHERE user_id=$1",
      [fixture.id],
    );
    assert.equal(
      (await request("/api/metrics", { headers: { cookie } })).status,
      401,
    );
    assert.equal((await request("/home", { headers: { cookie } })).status, 307);
    cookie = await login(fixture);
    assert.equal((await post("sign-out", {}, cookie)).status, 200);
    assert.equal(
      (await request("/api/metrics", { headers: { cookie } })).status,
      401,
    );
  }
  console.log(
    "PASS local production build, loopback PGlite database, two-account isolation, expired sessions, sign-out and closed registration.",
  );
} finally {
  if (app && app.exitCode === null)
    await new Promise((resolve) => {
      app.once("exit", resolve);
      app.kill("SIGTERM");
    });
  await databaseServer.stop();
  await db.close();
}
